using Microsoft.EntityFrameworkCore; using Movies.Database; using Movies.Domain;
namespace Movies.Services;
public sealed class MovieService(MoviesDbContext db) : IMovieService { public async Task<IReadOnlyList<MovieResponseDto>> GetActiveAsync(string? search, CancellationToken token) { var query=db.Movies.AsNoTracking().Where(x=>x.Status!=MovieStatus.Withdrawn); if(!string.IsNullOrWhiteSpace(search)) query=query.Where(x=>x.Title.Contains(search)||x.Genre.Contains(search)); return await query.OrderBy(x=>x.PremiereDate).Select(x=>new MovieResponseDto { Id=x.Id,Title=x.Title,Description=x.Description,Genre=x.Genre,DurationMinutes=x.DurationMinutes,PremiereDate=x.PremiereDate,AgeRating=x.AgeRating,PosterBase64=x.PosterBase64,AverageRating=x.AverageRating,Status=x.Status }).ToListAsync(token); } public async Task<MovieResponseDto> CreateAsync(CreateMovieRequestDto request, CancellationToken token) { var movie=new Movie { Id=Guid.NewGuid(),Title=request.Title.Trim(),Description=request.Description.Trim(),Genre=request.Genre.Trim(),DurationMinutes=request.DurationMinutes,PremiereDate=request.PremiereDate,AgeRating=request.AgeRating.Trim(),PosterBase64=request.PosterBase64,Status=request.Status,AverageRating=0 }; db.Movies.Add(movie); await db.SaveChangesAsync(token); return new MovieResponseDto { Id=movie.Id,Title=movie.Title,Description=movie.Description,Genre=movie.Genre,DurationMinutes=movie.DurationMinutes,PremiereDate=movie.PremiereDate,AgeRating=movie.AgeRating,PosterBase64=movie.PosterBase64,AverageRating=movie.AverageRating,Status=movie.Status }; } }
